const readIds=key=>{try{return JSON.parse(localStorage.getItem(key)||'[]').filter(Number.isInteger)}catch{return[]}};
const state={wishlist:readIds('kala-wishlist'),bag:readIds('kala-bag'),marketListings:[],artistDirectory:[],marketCategory:'All',limit:8,query:'',category:'',sort:'featured',account:null,accountMode:'login',pendingContactId:null,contactArtworkId:null};
const imageUrl=id=>id;
const rupees=n=>'₹'+Number(n||0).toLocaleString('en-IN');
const escapeHtml=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const findArtwork=id=>artworks.find(art=>art.id===Number(id))||state.marketListings.find(art=>art.id===Number(id));
async function api(path,options={}){
  const headers={...(options.body?{'Content-Type':'application/json'}:{}),...(options.headers||{})};
  let response;
  try{response=await fetch(path,{...options,headers,credentials:'same-origin'})}
  catch{throw new Error('KALA API is not running. Open a terminal in the KALA folder, run node server.js, then open http://127.0.0.1:3000.')}
  const result=await response.json().catch(()=>({}));
  if(!response.ok)throw new Error(result.error||'The request could not be completed.');
  return result;
}
function persist(){if(!state.account){localStorage.setItem('kala-wishlist',JSON.stringify(state.wishlist));localStorage.setItem('kala-bag',JSON.stringify(state.bag))}updateBagCount()}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),3000)}
function render(){let list=artworks.filter(a=>(!state.category||a.category===state.category)&&(!state.query||`${a.title} ${a.artist} ${a.place} ${a.style} ${a.category}`.toLowerCase().includes(state.query.toLowerCase())));if(state.sort==='artist')list.sort((a,b)=>a.artist.localeCompare(b.artist));const shown=list.slice(0,state.limit);document.querySelector('#result-count').textContent=`Showing ${shown.length} of ${list.length} documented Indian works`;document.querySelector('#clear-filters').classList.toggle('hidden',!state.query&&!state.category);document.querySelector('#load-more').classList.toggle('hidden',shown.length>=list.length);document.querySelector('#art-grid').innerHTML=shown.map(a=>`<article class="art-card" data-id="${a.id}"><div class="art-image-wrap"><img class="art-image" src="${imageUrl(a.image)}" alt="${a.title}, by ${a.artist}" loading="lazy"><span class="art-badge">${a.category}</span><button class="wish-button ${state.wishlist.includes(a.id)?'active':''}" data-wish="${a.id}" aria-label="${state.wishlist.includes(a.id)?'Remove from':'Add to'} liked art">${state.wishlist.includes(a.id)?'♥':'♡'}</button><button class="quick-view" data-detail="${a.id}">VIEW DETAILS &nbsp; ↗</button></div><div class="art-info"><div class="art-title-row"><span class="art-title">${a.title}</span></div><p class="art-artist">${a.artist} · ${a.place}</p><div class="art-meta"><span>${a.style}</span></div><p class="art-sample-price">Sample reference price <b>${rupees(a.samplePrice)}</b></p></div></article>`).join('')||'<p>No works found. Try another search or clear your filters.</p>';document.querySelectorAll('.art-card').forEach(el=>el.addEventListener('click',e=>{if(e.target.closest('button'))return;openDetail(Number(el.dataset.id))}));document.querySelectorAll('[data-wish]').forEach(b=>b.addEventListener('click',e=>{e.stopPropagation();toggleWish(Number(b.dataset.wish))}));document.querySelectorAll('[data-detail]').forEach(b=>b.addEventListener('click',e=>{e.stopPropagation();openDetail(Number(b.dataset.detail))}));}
async function toggleWish(id){try{if(state.account){const path=`/api/favorites/${id}`;const result=state.wishlist.includes(id)?await api(path,{method:'DELETE'}):await api(path,{method:'PUT'});state.wishlist=result.artworkIds}else if(state.wishlist.includes(id)){state.wishlist=state.wishlist.filter(x=>x!==id)}else{state.wishlist.push(id)}persist();render();renderMarketplace();renderLiked();if(document.querySelector('#detail-overlay:not(.hidden)'))openDetail(id);toast(state.wishlist.includes(id)?'Added to liked art':'Removed from liked art')}catch(error){toast(error.message)}}
function contactName(art){return /^(unknown|traditional)/i.test(art.artist)?'KALA Art Desk':art.artist}
function openDetail(id){const a=findArtwork(id);if(!a)return;const images=(Array.isArray(a.images)&&a.images.length?a.images:[a.image]).filter(Boolean);const samplePrice=a.forSale?a.price:a.samplePrice;const priceLabel=a.forSale?'Sample price':'Indicative sample price';document.querySelector('#detail-content').innerHTML=`<div class="detail-layout"><div class="detail-gallery"><img id="detail-gallery-main" src="${escapeHtml(imageUrl(images[0]))}" alt="${escapeHtml(a.title)}${images.length>1?' · photo 1':''}"/>${images.length>1?`<div class="gallery-controls"><button type="button" data-gallery-prev aria-label="Previous photo">‹</button><span id="gallery-position">1 / ${images.length}</span><button type="button" data-gallery-next aria-label="Next photo">›</button></div><div class="gallery-thumbnails">${images.map((src,index)=>`<button type="button" class="gallery-thumb${index===0?' active':''}" data-gallery-index="${index}" aria-label="Show photo ${index+1}"><img src="${escapeHtml(imageUrl(src))}" alt=""></button>`).join('')}</div>`:''}</div><div class="detail-text"><p class="eyebrow">${escapeHtml(a.style).toUpperCase()} · ${escapeHtml(a.place).toUpperCase()}</p><h2>${escapeHtml(a.title)}</h2><p class="detail-artist">Artist / studio: <b>${escapeHtml(a.artist)}</b></p><p class="detail-description">${escapeHtml(a.description)}</p><div class="detail-specs">${a.medium?`<span>Medium<b>${escapeHtml(a.medium)}</b></span>`:''}${a.dimensions?`<span>Collection record<b>${escapeHtml(a.dimensions)}</b></span>`:''}<span>Date<b>${escapeHtml(a.year||'Artist listing')}</b></span>${samplePrice?`<span>${priceLabel}<b>${rupees(samplePrice)}</b></span>`:''}${!a.forSale?`<span>Image credit<b>${escapeHtml(a.credit||'KALA sample catalog')}</b></span>`:''}</div>${a.isSample?'<p class="sample-image-note">Demo listing: the displayed image is a tradition reference, not the item for sale.</p>':''}${a.samplePrice?'<p class="sample-image-note">Indicative reference price only. This documented collection work is not an offer for sale.</p>':''}<div class="detail-buttons">${a.source?`<a class="button button-outline" href="${escapeHtml(a.source)}" target="_blank" rel="noopener noreferrer">Open source record <span>↗</span></a>`:''}${a.forSale?'<button class="button button-outline" id="detail-cart">Add to cart</button>':''}<button class="button button-dark" id="detail-contact">Contact artist</button><button class="button button-outline" id="detail-wish">${state.wishlist.includes(id)?'♥ Liked':'♡ Like art'}</button></div></div></div>`;showOverlay('detail-overlay');if(images.length>1){let index=0;const main=document.querySelector('#detail-gallery-main');const position=document.querySelector('#gallery-position');const updateGallery=next=>{index=(next+images.length)%images.length;main.src=imageUrl(images[index]);main.alt=`${a.title} · photo ${index+1}`;position.textContent=`${index+1} / ${images.length}`;document.querySelectorAll('.gallery-thumb').forEach((button,i)=>button.classList.toggle('active',i===index))};document.querySelector('[data-gallery-prev]').onclick=()=>updateGallery(index-1);document.querySelector('[data-gallery-next]').onclick=()=>updateGallery(index+1);document.querySelectorAll('[data-gallery-index]').forEach(button=>button.onclick=()=>updateGallery(Number(button.dataset.galleryIndex)))}document.querySelector('#detail-cart')?.addEventListener('click',()=>addBag(id));document.querySelector('#detail-contact').onclick=()=>openContact(id);document.querySelector('#detail-wish').onclick=()=>toggleWish(id)}
async function addBag(id){const art=findArtwork(id);if(!art?.forSale){toast('This archival artwork is a reference, not a sale listing. Browse the artist stores for items to add.');return}try{if(state.account){const result=await api('/api/cart',{method:'POST',body:JSON.stringify({artworkId:id})});state.bag=result.artworkIds}else if(!state.bag.includes(id)){state.bag.push(id)}else{toast('This artwork is already in your cart');return}persist();renderBag();toast('Added to your cart')}catch(error){toast(error.message)}}
async function removeBag(id){try{if(state.account){const result=await api(`/api/cart/${id}`,{method:'DELETE'});state.bag=result.artworkIds}else state.bag=state.bag.filter(item=>item!==id);persist();renderBag()}catch(error){toast(error.message)}}
function updateBagCount(){document.querySelector('#bag-count').textContent=state.bag.length;document.querySelector('#bag-title-count').textContent=`(${state.bag.length})`;document.querySelector('#liked-count').textContent=state.wishlist.length;document.querySelector('#liked-title-count').textContent=`(${state.wishlist.length})`}
function renderBag(){const items=state.bag.map(findArtwork).filter(Boolean);document.querySelector('#bag-items').innerHTML=items.length?`<div class="bag-list">${items.map(a=>`<div class="bag-item"><img src="${a.image}" alt="${a.title}"><div><b>${a.title}</b><p>${a.artist} · ${rupees(a.price)}</p><button data-remove="${a.id}">Remove</button> <button data-contact-item="${a.id}">Contact artist</button></div></div>`).join('')}</div>`:'<p class="empty-bag">Your cart is waiting for a piece with a story.<br>Add an artist-store listing to keep it here.</p>';document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>removeBag(Number(b.dataset.remove)));document.querySelectorAll('[data-contact-item]').forEach(b=>b.onclick=()=>openContact(Number(b.dataset.contactItem)))}
function renderLiked(){const items=state.wishlist.map(findArtwork).filter(Boolean);document.querySelector('#liked-items').innerHTML=items.length?`<div class="bag-list">${items.map(a=>`<div class="bag-item"><img src="${a.image}" alt="${a.title}"><div><b>${a.title}</b><p>${a.artist}</p><button data-unlike="${a.id}">Unlike</button> <button data-detail="${a.id}">View</button></div></div>`).join('')}</div>`:'<p class="empty-bag">Tap the heart on an artwork to save it here.</p>';document.querySelectorAll('[data-unlike]').forEach(b=>b.onclick=()=>toggleWish(Number(b.dataset.unlike)));document.querySelectorAll('#liked-items [data-detail]').forEach(b=>b.onclick=()=>openDetail(Number(b.dataset.detail)))}
function renderMarketplace(){const grid=document.querySelector('#market-grid');if(!grid)return;const listings=state.marketCategory==='All'?state.marketListings:state.marketListings.filter(art=>(art.category||'Painting')===state.marketCategory);grid.innerHTML=listings.map(art=>`<article class="market-card"><div class="market-image"><img src="${art.image}" alt="${escapeHtml(art.title)}" loading="lazy"><span class="market-badge">${escapeHtml(art.category||'Painting')} · ${art.isSample?'SAMPLE':'ARTIST LISTING'}</span>${art.images?.length>1?`<span class="market-photo-count">${art.images.length} photos</span>`:''}<button class="wish-button ${state.wishlist.includes(art.id)?'active':''}" data-market-wish="${art.id}" aria-label="Like ${escapeHtml(art.title)}">${state.wishlist.includes(art.id)?'♥':'♡'}</button></div><div class="market-info"><small>${escapeHtml(art.style)} · ${escapeHtml(art.place)}</small><h3>${escapeHtml(art.title)}</h3><p>${escapeHtml(art.artist)}</p><strong>${rupees(art.price)}${art.isSample?' <small>sample</small>':''}</strong>${art.isSample?'<p class="sample-image-note">Demo only: this licensed reference photo shows the tradition, not the sample item.</p>':''}${art.source?`<a class="market-credit" href="${escapeHtml(art.source)}" target="_blank" rel="noopener noreferrer">Image: ${escapeHtml(art.credit||'View source and license')} ↗</a>`:''}<div class="market-actions"><button class="button button-outline" data-market-detail="${art.id}">Details</button><button class="button button-dark" data-market-cart="${art.id}">Add to cart</button><button class="text-link" data-market-contact="${art.id}">Message artist</button></div></div></article>`).join('')||'<p class="empty-bag">No listings in this category yet. Artists can add one from Artist Studio.</p>';grid.querySelectorAll('[data-market-wish]').forEach(button=>button.onclick=()=>toggleWish(Number(button.dataset.marketWish)));grid.querySelectorAll('[data-market-detail]').forEach(button=>button.onclick=()=>openDetail(Number(button.dataset.marketDetail)));grid.querySelectorAll('[data-market-cart]').forEach(button=>button.onclick=()=>addBag(Number(button.dataset.marketCart)));grid.querySelectorAll('[data-market-contact]').forEach(button=>button.onclick=()=>openContact(Number(button.dataset.marketContact)))}
function renderArtistDirectory(){const target=document.querySelector('#artist-directory');if(!target)return;target.innerHTML=state.artistDirectory.map(artist=>`<article class="artist-store-card"><span>${artist.isSample?'SAMPLE ARTIST':'KALA ARTIST'}</span><h3>${escapeHtml(artist.name)}</h3><p>${escapeHtml(artist.city)} · ${escapeHtml(artist.artForms)}</p><small>${escapeHtml(artist.bio)}</small></article>`).join('')}
async function loadMarketplace(){try{const [market,artistsResult]=await Promise.all([api('/api/artworks'),api('/api/artists')]);state.marketListings=market.listings;state.artistDirectory=artistsResult.artists;document.querySelector('#market-status').textContent='Sample store profiles and prices are illustrative. Reuse terms for reference photos are linked on each listing; real artists can add their own craft or artwork and store details in Artist Studio.';renderMarketplace();renderArtistDirectory();renderBag();renderLiked()}catch(error){document.querySelector('#market-status').textContent=error.message;renderMarketplace()}}
function showOverlay(id){document.querySelector('#'+id).classList.remove('hidden');document.body.style.overflow='hidden'}function hideOverlay(id){document.querySelector('#'+id).classList.add('hidden');if(!document.querySelector('.overlay:not(.hidden)'))document.body.style.overflow=''}
function setAccountMessage(text){document.querySelector('#account-message').textContent=text}
function updateAccountUI(){const signedIn=Boolean(state.account),isArtist=state.account?.role==='artist';document.querySelector('#artist-studio-open').classList.toggle('hidden',!isArtist);document.querySelector('#account-form').classList.toggle('hidden',signedIn);document.querySelector('#account-switch').classList.toggle('hidden',signedIn);document.querySelector('#account-logout').classList.toggle('hidden',!signedIn);const summary=document.querySelector('#account-summary');summary.classList.toggle('hidden',!signedIn);if(signedIn){document.querySelector('#account-title').innerHTML=isArtist?'Welcome to your<br><em>studio.</em>':'Welcome back,<br><em>art lover.</em>';document.querySelector('#account-copy').textContent='Your account keeps your KALA activity together.';summary.innerHTML=`<p>Signed in as <b>${escapeHtml(state.account.name)}</b><br>${escapeHtml(state.account.email)} · ${isArtist?'Artist':'Art lover'}</p><button type="button" class="button button-outline" id="account-area-button">${isArtist?'Open Artist Studio':'View artist inquiries'}</button>`;document.querySelector('#account-area-button').onclick=()=>isArtist?openArtistStudio():openInquiries()}else{document.querySelector('#account-title').innerHTML='A world of art<br><em>awaits you.</em>';document.querySelector('#account-copy').textContent='Sign in or create an art lover or artist account.'}const signup=state.accountMode==='register';document.querySelector('#account-name').classList.toggle('hidden',!signup);document.querySelector('.account-name-label').classList.toggle('hidden',!signup);document.querySelector('#account-name').required=signup;document.querySelector('#account-password').autocomplete=signup?'new-password':'current-password';document.querySelector('#account-password').minLength=signup?10:1;document.querySelector('#account-submit').innerHTML=signup?'Create account <span>↗</span>':'Sign in <span>↗</span>';document.querySelector('#account-switch').textContent=signup?'Already have an account? Sign in':'New to KALA? Create an account'}async function syncAccountCollections(mergeGuest=false){if(mergeGuest){const guestCart=[...state.bag],guestLikes=[...state.wishlist];for(const artworkId of guestCart)await api('/api/cart',{method:'POST',body:JSON.stringify({artworkId})});for(const artworkId of guestLikes)await api(`/api/favorites/${artworkId}`,{method:'PUT'});localStorage.removeItem('kala-bag');localStorage.removeItem('kala-wishlist')}const [cart,favorites]=await Promise.all([api('/api/cart'),api('/api/favorites')]);state.bag=cart.artworkIds;state.wishlist=favorites.artworkIds;persist();render();renderBag();renderLiked()}
async function syncAccountCollections(mergeGuest=false){if(mergeGuest){const guestCart=[...state.bag],guestLikes=[...state.wishlist];for(const artworkId of guestCart)await api('/api/cart',{method:'POST',body:JSON.stringify({artworkId})});for(const artworkId of guestLikes)await api(`/api/favorites/${artworkId}`,{method:'PUT'});localStorage.removeItem('kala-bag');localStorage.removeItem('kala-wishlist')}const [cart,favorites]=await Promise.all([api('/api/cart'),api('/api/favorites')]);state.bag=cart.artworkIds;state.wishlist=favorites.artworkIds;persist();render();renderMarketplace();renderBag();renderLiked()}
async function submitAccount(event){event.preventDefault();const signup=state.accountMode==='register',body={email:document.querySelector('#account-email').value,password:document.querySelector('#account-password').value,role:document.querySelector('#account-role').value};if(signup)body.name=document.querySelector('#account-name').value;try{const result=await api(signup?'/api/auth/register':'/api/auth/login',{method:'POST',body:JSON.stringify(body)});state.account=result.user;await syncAccountCollections(signup);updateAccountUI();setAccountMessage('');toast(signup?'Your KALA account is ready.':'You are signed in.');hideOverlay('account-overlay');if(state.pendingContactId){const id=state.pendingContactId;state.pendingContactId=null;openContact(id)}}catch(error){setAccountMessage(error.message)}}
function openContact(id){const art=findArtwork(id);if(!art)return;if(!state.account||state.account.role!=='user'){state.pendingContactId=id;showOverlay('account-overlay');setAccountMessage(!state.account?'Sign in or create an art lover account to send an artist message.':'Artist accounts can receive messages from their inbox.');return}state.contactArtworkId=id;document.querySelector('#contact-recipient').textContent=`To: ${contactName(art)} · About: ${art.title}`;document.querySelector('#contact-message').value='';document.querySelector('#contact-status').textContent='';showOverlay('contact-overlay')}
async function submitContact(event){event.preventDefault();const art=findArtwork(state.contactArtworkId);if(!art)return;const button=event.submitter||document.querySelector('#contact-form .button');button.disabled=true;try{const result=await api('/api/messages',{method:'POST',body:JSON.stringify({artistName:contactName(art),artworkId:art.id,artworkTitle:art.title,message:document.querySelector('#contact-message').value})});document.querySelector('#contact-status').textContent=result.message.routed?'Message delivered to the artist’s KALA inbox.':'Message saved. It will appear in the artist’s inbox when they create a matching KALA artist account.';document.querySelector('#contact-message').value='';toast(result.message.routed?'Message sent to artist':'Message saved for artist')}catch(error){document.querySelector('#contact-status').textContent=error.message}finally{button.disabled=false}}
function renderStudioListings(listings){const host=document.querySelector('#my-art-listings');host.innerHTML=listings.length?listings.map(item=>`<article class="studio-listing"><img src="${escapeHtml(item.image)}" alt=""><div><b>${escapeHtml(item.title)}</b><span>${escapeHtml(item.style)} · ${rupees(item.price)}</span><small>${item.images?.length||1} photo${(item.images?.length||1)===1?'':'s'}</small></div><button type="button" class="text-link" data-delete-listing="${item.id}">Remove listing</button></article>`).join(''):'<p class="empty-bag">You have not published a store listing yet.</p>';host.querySelectorAll('[data-delete-listing]').forEach(button=>button.onclick=async()=>{try{await api(`/api/artist/listings/${button.dataset.deleteListing}`,{method:'DELETE'});toast('Listing removed');await openArtistStudio()}catch(error){document.querySelector('#studio-status').textContent=error.message}})}
async function openArtistStudio(){if(state.account?.role!=='artist'){toast('Sign in with an artist account to open Artist Studio.');return}showOverlay('artist-studio-overlay');document.querySelector('#studio-status').textContent='Loading your store…';try{const [profileResult,listingsResult]=await Promise.all([api('/api/artist/profile'),api('/api/artist/listings')]);const profile=profileResult.profile;document.querySelector('#studio-name').value=profile.name||state.account.name;document.querySelector('#studio-city').value=profile.city||'';document.querySelector('#studio-forms').value=profile.artForms||'';document.querySelector('#studio-bio').value=profile.bio||'';renderStudioListings(listingsResult.listings);document.querySelector('#studio-status').textContent='Your store details and listings are saved in KALA.'}catch(error){document.querySelector('#studio-status').textContent=error.message}}
async function saveArtistProfile(event){event.preventDefault();try{const result=await api('/api/artist/profile',{method:'PUT',body:JSON.stringify({name:document.querySelector('#studio-name').value,city:document.querySelector('#studio-city').value,artForms:document.querySelector('#studio-forms').value,bio:document.querySelector('#studio-bio').value})});state.account=result.user;updateAccountUI();document.querySelector('#studio-status').textContent='Store details saved.';await loadMarketplace();toast('Artist store updated')}catch(error){document.querySelector('#studio-status').textContent=error.message}}
function fileAsDataUrl(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=()=>reject(new Error('Could not read the selected image.'));reader.onload=()=>resolve(String(reader.result));reader.readAsDataURL(file)})}
function clearImagePreviews(){const preview=document.querySelector('#listing-image-preview');try{JSON.parse(preview.dataset.urls||'[]').forEach(URL.revokeObjectURL)}catch{}preview.dataset.urls='[]';preview.replaceChildren();preview.classList.add('hidden')}
async function createArtistListing(event){event.preventDefault();const form=event.currentTarget;const submit=form.querySelector('button');const imageFiles=[...document.querySelector('#listing-image').files];submit.disabled=true;try{if(imageFiles.length<1||imageFiles.length>6)throw new Error('Choose between 1 and 6 photos for this listing.');document.querySelector('#studio-status').textContent='Uploading artwork photos…';const images=[];for(let index=0;index<imageFiles.length;index++){document.querySelector('#studio-status').textContent=`Uploading photo ${index+1} of ${imageFiles.length}…`;const upload=await api('/api/artist/images',{method:'POST',body:JSON.stringify({dataUrl:await fileAsDataUrl(imageFiles[index])})});images.push(upload.image)}await api('/api/artist/listings',{method:'POST',body:JSON.stringify({title:document.querySelector('#listing-title').value,category:document.querySelector('#listing-category').value,style:document.querySelector('#listing-style').value,medium:document.querySelector('#listing-medium').value,price:document.querySelector('#listing-price').value,images,description:document.querySelector('#listing-description').value})});form.reset();clearImagePreviews();document.querySelector('#studio-status').textContent=`Your listing and ${images.length} photos are now published in your store.`;toast('Store listing published');await loadMarketplace();await openArtistStudio()}catch(error){document.querySelector('#studio-status').textContent=error.message}finally{submit.disabled=false}}
function renderConversationThread(message){const replies=Array.isArray(message.replies)?message.replies:(message.reply?[{fromRole:'artist',fromName:message.artistName,body:message.reply,createdAt:message.repliedAt||message.createdAt}]:[]);const entries=[{fromRole:'user',fromName:message.fromName||'Art lover',body:message.body,createdAt:message.createdAt},...replies];return entries.map(item=>`<div class="message-bubble ${item.fromRole==='artist'?'from-artist':'from-user'}"><b>${escapeHtml(item.fromName||(item.fromRole==='artist'?message.artistName:'Art lover'))}</b><p>${escapeHtml(item.body)}</p><small>${item.createdAt?new Date(item.createdAt).toLocaleString():''}</small></div>`).join('')}
function bindConversationReplies(host,role,refresh){host.querySelectorAll('[data-thread-reply]').forEach(form=>form.addEventListener('submit',async event=>{event.preventDefault();const button=form.querySelector('button');button.disabled=true;const endpoint=role==='artist'?`/api/artist/messages/${form.dataset.threadReply}/reply`:`/api/messages/${form.dataset.threadReply}/reply`;try{await api(endpoint,{method:'POST',body:JSON.stringify({reply:form.elements.reply.value})});toast('Message sent');await refresh()}catch(error){toast(error.message);button.disabled=false}}))}
async function openArtistInbox(){if(state.account?.role!=='artist'){toast('Sign in with an artist account to open the inbox.');return}showOverlay('artist-inbox-overlay');const host=document.querySelector('#artist-inbox-items');host.innerHTML='<p class="empty-bag">Loading messages…</p>';try{const result=await api('/api/artist/messages');host.innerHTML=result.messages.length?result.messages.map(message=>`<article class="inbox-message"><p class="eyebrow">${escapeHtml(message.artworkTitle||'ARTIST INQUIRY')}</p><h3>Conversation with ${escapeHtml(message.fromName)}</h3><div class="conversation-thread">${renderConversationThread(message)}</div><form class="reply-form" data-thread-reply="${message.id}"><label>Reply to art lover</label><textarea name="reply" maxlength="3000" required placeholder="Write a message…"></textarea><button class="button button-dark">Send message</button></form></article>`).join(''):'<p class="empty-bag">No artist messages yet. Messages addressed to your artist name will appear here.</p>';bindConversationReplies(host,'artist',openArtistInbox)}catch(error){host.innerHTML=`<p class="empty-bag">${escapeHtml(error.message)}</p>`}}
async function openInquiries(){if(state.account?.role!=='user'){toast('Sign in with an art lover account to see your messages.');return}showOverlay('inquiries-overlay');const host=document.querySelector('#inquiries-items');host.innerHTML='<p class="empty-bag">Loading inquiries…</p>';try{const result=await api('/api/messages');host.innerHTML=result.messages.length?result.messages.map(message=>`<article class="inbox-message"><p class="eyebrow">${escapeHtml(message.artworkTitle||'ARTIST INQUIRY')}</p><h3>Conversation with ${escapeHtml(message.artistName)}</h3><div class="conversation-thread">${renderConversationThread(message)}</div><form class="reply-form" data-thread-reply="${message.id}"><label>Reply to artist</label><textarea name="reply" maxlength="3000" required placeholder="Write a message…"></textarea><button class="button button-dark">Send message</button></form></article>`).join(''):'<p class="empty-bag">Your artist messages and replies will appear here.</p>';bindConversationReplies(host,'user',openInquiries)}catch(error){host.innerHTML=`<p class="empty-bag">${escapeHtml(error.message)}</p>`}}
async function restoreAccount(){try{const result=await api('/api/me');state.account=result.user;await syncAccountCollections(false);updateAccountUI()}catch{state.account=null;updateAccountUI();persist()}}
function init(){const select=document.querySelector('#category-filter');[...new Set(categories)].forEach(c=>select.insertAdjacentHTML('beforeend',`<option value="${c}">${categoryLabel(c)}</option>`));document.querySelector('#category-list').innerHTML=categories.slice(0,10).map(c=>`<a class="category-item" href="#explore" data-category="${c}"><span>${categoryLabel(c)}</span><span>↗</span></a>`).join('');document.querySelector('#showpiece-grid').innerHTML=showpieces.map((x,i)=>`<button class="showpiece-card showpiece-${i+1}" type="button" data-category="${x.filter}" aria-label="Explore ${x.name} art"><img src="${imageUrl(x.image)}" alt="Artwork inspired by ${x.name}" loading="lazy"><span class="showpiece-overlay"></span><span class="showpiece-text"><small>${x.region}</small><b>${x.name}</b><i>${x.note}</i><span class="showpiece-link">EXPLORE THE FORM &nbsp; ↗</span></span></button>`).join('');document.querySelector('#artist-grid').innerHTML=artists.map(a=>`<article class="artist-card"><img loading="lazy" src="${imageUrl(a.image)}" alt="${a.name}"><div class="artist-card-info"><b>${a.name}</b><span>${a.place} · ${a.style}</span></div></article>`).join('');render();renderBag();renderLiked();renderMarketplace();renderArtistDirectory();updateAccountUI();document.querySelector('#search-input').oninput=e=>{state.query=e.target.value;state.limit=8;render()};document.querySelector('#category-filter').onchange=e=>{state.category=e.target.value;state.limit=8;render()};document.querySelector('#sort-filter').onchange=e=>{state.sort=e.target.value;render()};document.querySelector('#clear-filters').onclick=()=>{state.query='';state.category='';document.querySelector('#search-input').value='';select.value='';render()};document.querySelector('#load-more').onclick=()=>{state.limit+=4;render()};document.querySelectorAll('[data-category]').forEach(el=>el.onclick=()=>{state.category=el.dataset.category;select.value=state.category;state.limit=8;render();document.querySelector('#explore').scrollIntoView({behavior:'smooth'})});document.querySelector('#search-open').onclick=()=>{document.querySelector('#explore').scrollIntoView();document.querySelector('#search-input').focus()};document.querySelector('#bag-open').onclick=()=>{renderBag();showOverlay('bag-overlay')};document.querySelector('#liked-open').onclick=()=>{renderLiked();showOverlay('liked-overlay')};document.querySelector('#account-open').onclick=()=>{setAccountMessage('');showOverlay('account-overlay')};document.querySelector('#artist-studio-open').onclick=openArtistStudio;document.querySelector('#artist-studio-inbox').onclick=()=>{hideOverlay('artist-studio-overlay');openArtistInbox()};document.querySelector('#account-form').onsubmit=submitAccount;document.querySelector('#account-switch').onclick=()=>{state.accountMode=state.accountMode==='login'?'register':'login';setAccountMessage('');updateAccountUI()};document.querySelector('#account-logout').onclick=async()=>{try{await api('/api/auth/logout',{method:'POST'})}catch{}state.account=null;state.bag=[];state.wishlist=[];persist();updateAccountUI();render();renderMarketplace();renderBag();renderLiked();hideOverlay('account-overlay');toast('You are signed out')};document.querySelector('#account-role').onchange=()=>{document.querySelector('#account-password').value=''};document.querySelector('#contact-form').onsubmit=submitContact;document.querySelector('#artist-profile-form').onsubmit=saveArtistProfile;document.querySelector('#artist-listing-form').onsubmit=createArtistListing;document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>hideOverlay(b.closest('.overlay').id));document.querySelectorAll('.overlay').forEach(o=>o.addEventListener('click',e=>{if(e.target===o)hideOverlay(o.id)}));document.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelectorAll('.overlay:not(.hidden)').forEach(o=>hideOverlay(o.id))});document.querySelector('#menu-toggle')?.addEventListener('click',()=>document.querySelector('.main-nav').classList.toggle('open'));document.querySelector('.menu-toggle').onclick=()=>document.querySelector('.main-nav').classList.toggle('open');document.querySelectorAll('.main-nav a').forEach(a=>a.onclick=()=>document.querySelector('.main-nav').classList.remove('open'));document.querySelector('#newsletter-form').onsubmit=e=>{e.preventDefault();toast('You’re on the list. Look out for a note from KALA.');e.target.reset()};loadMarketplace();restoreAccount()}
document.querySelectorAll('[data-market-filter]').forEach(button=>button.addEventListener('click',()=>{state.marketCategory=button.dataset.marketFilter;document.querySelectorAll('[data-market-filter]').forEach(item=>item.classList.toggle('active',item===button));renderMarketplace()}));
document.querySelector('#listing-image').addEventListener('change',event=>{clearImagePreviews();const files=[...event.target.files];const preview=document.querySelector('#listing-image-preview');if(!files.length)return;if(files.length>6||files.some(file=>!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>4*1024*1024)){event.target.value='';document.querySelector('#studio-status').textContent='Choose 1–6 JPEG, PNG, or WebP photos, each under 4 MB.';return}const urls=[];files.forEach((file,index)=>{const url=URL.createObjectURL(file);urls.push(url);const figure=document.createElement('figure');const img=document.createElement('img');img.src=url;img.alt=`Selected artwork photo ${index+1}`;const caption=document.createElement('figcaption');caption.textContent=file.name;figure.append(img,caption);preview.append(figure)});preview.dataset.urls=JSON.stringify(urls);preview.classList.remove('hidden')});
init();

