function renderHeritageWorks(filter='all'){
  const works=heritagePaintings.filter(art=>filter==='all'||art.kind===filter);
  document.querySelector('#showpiece-grid').innerHTML=works.map(art=>`<article class="heritage-piece"><div class="showpiece-card"><img src="${art.image}" alt="${art.alt}" loading="lazy"><span class="work-type">${art.kind==='handicraft'?'Handicraft':art.kind==='sculpture'?'Sculpture':'Painting'}</span></div><div class="showpiece-text"><small>${art.maker}</small><b>${art.title}</b><i>${art.date} · ${art.medium}</i></div><a class="showpiece-credit" href="${art.source}" target="_blank" rel="noopener noreferrer">${art.credit} <span>↗</span></a></article>`).join('');
}
renderHeritageWorks();
document.querySelectorAll('[data-heritage-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-heritage-filter]').forEach(item=>item.classList.toggle('active',item===button));renderHeritageWorks(button.dataset.heritageFilter)}));

