function renderImageCredit(imageCredit, imageSource){
  const [credit,...terms]=imageCredit.split(' · '), license=terms.at(-1), licenseUrls={'CC0 1.0':'https://creativecommons.org/publicdomain/zero/1.0/','CC BY 2.0':'https://creativecommons.org/licenses/by/2.0/','CC BY 4.0':'https://creativecommons.org/licenses/by/4.0/','CC BY-SA 2.0':'https://creativecommons.org/licenses/by-sa/2.0/','CC BY-SA 3.0':'https://creativecommons.org/licenses/by-sa/3.0/','CC BY-SA 4.0':'https://creativecommons.org/licenses/by-sa/4.0/','Public Domain':'https://creativecommons.org/publicdomain/mark/1.0/'};
  return `<a href="${imageSource}" target="_blank" rel="noopener noreferrer">${credit}</a>${license?` · <a href="${licenseUrls[license]||imageSource}" target="_blank" rel="noopener noreferrer">${license}</a>`:''}`;
}
function renderTraditionGroup(list, target, includeImages=false){
  document.querySelector(target).innerHTML=list.map(([name,region,category,features,reference,source,image,imageSource,imageCredit])=>`<article class="tradition-card${image?' has-art-image':''}"><div class="tradition-card-head"><h4>${name}</h4><span>${category}</span></div><p class="tradition-region">${region}</p>${includeImages&&image?`<figure class="tradition-art"><a href="${imageSource}" target="_blank" rel="noopener noreferrer"><img src="${image}" alt="${reference}, an example of ${name}" loading="lazy"></a><figcaption>${renderImageCredit(imageCredit,imageSource)}</figcaption></figure>`:''}<p>${features}</p><a class="tradition-reference" href="${source}" target="_blank" rel="noopener noreferrer">Tradition reference: ${reference} <span>↗</span></a></article>`).join('');
}
renderTraditionGroup(traditionGuide.painting,'#painting-traditions',true);
renderTraditionGroup(traditionGuide.sculpture,'#sculpture-traditions');

